# Add direct predictor-boundary integration coverage. The tone_bridge unit tests
# already prove prefix/later-suffix immutability; these tests prove the shared
# runtime contract applies once, waits through forecasts, and records provenance.
replace_once(
    "tests/test_continuum_suffix_bridge.py",
    '''from __future__ import annotations\n\nimport torch\n\nfrom h3_flow_regenerate.geometry import pack_streams\nfrom h3_flow_regenerate.runtime import _contiguous_exact_video_prefix\n''',
    '''from __future__ import annotations\n\nfrom types import SimpleNamespace\n\nimport torch\n\nfrom h3_flow_regenerate.geometry import pack_streams, unpack_streams\nfrom h3_flow_regenerate.runtime import (\n    EXACT_PREFIX_BRIDGE_KEY,\n    FLOW_BINDING_KEY,\n    SPECTRUM_ACTUAL_KEY,\n    FlowBinding,\n    _contiguous_exact_video_prefix,\n    flow_predict_wrapper,\n)\n''',
)
Path("tests/test_continuum_suffix_bridge.py").write_text(
    Path("tests/test_continuum_suffix_bridge.py").read_text()
    + '''\n\nclass _PredictExecutor:\n    def __init__(self, guider, result):\n        self.class_obj = guider\n        self.result = result\n\n    def __call__(self, _x, _timestep, _model_options, _seed):\n        return self.result.clone()\n\n\ndef _predict_bridge_fixture(*, actual=True):\n    video = torch.zeros(1, 24, 3, 2, 2)\n    video[:, :, 0] = 1.0\n    video[:, :, 1] = 3.0\n    video[:, :, 2] = 5.0\n    audio = torch.zeros(1, 32, 2, 3)\n    packed, shapes = pack_streams((video, audio))\n    exact_prefix = torch.full((1, 24, 1, 2, 2), 2.0)\n    contract = {"exact_prefix": exact_prefix, "source": "unit", "applied": False}\n    transformer = {\n        EXACT_PREFIX_BRIDGE_KEY: contract,\n        SPECTRUM_ACTUAL_KEY: bool(actual),\n    }\n    binding = FlowBinding()\n    guider = SimpleNamespace(\n        model_options={FLOW_BINDING_KEY: binding, "transformer_options": transformer},\n        inner_model=SimpleNamespace(latent_shapes=list(shapes)),\n    )\n    executor = _PredictExecutor(guider, packed)\n    return video, packed, shapes, contract, binding, guider, executor\n\n\ndef test_predict_bridge_applies_once_to_first_suffix_token_and_records_provenance():\n    video, packed, shapes, contract, binding, guider, executor = _predict_bridge_fixture(actual=True)\n\n    first = flow_predict_wrapper(\n        executor,\n        packed,\n        torch.tensor([0.5]),\n        guider.model_options,\n        7,\n    )\n    first_video, _ = unpack_streams(first, shapes)\n    assert torch.equal(first_video[:, :, :1], video[:, :, :1])\n    assert torch.equal(first_video[:, :, 2:], video[:, :, 2:])\n    assert torch.equal(first_video[:, :, 1], video[:, :, 1] + 1.0)\n    assert contract["applied"] is True\n\n    bridge_events = [event for event in binding.metrics.events if event.kind == "exact_prefix_suffix_dc_bridge"]\n    assert len(bridge_events) == 1\n    assert bridge_events[0].fields["source"] == "unit"\n    assert bridge_events[0].fields["actual"] is True\n    assert bridge_events[0].fields["suffix_dc_bridge_corrected_tokens"] == 1\n    assert bridge_events[0].fields["suffix_dc_bridge_state_mapping"] == "first_actual_model_x0"\n\n    second = flow_predict_wrapper(\n        executor,\n        packed,\n        torch.tensor([0.4]),\n        guider.model_options,\n        7,\n    )\n    assert torch.equal(second, packed)\n    assert len([event for event in binding.metrics.events if event.kind == "exact_prefix_suffix_dc_bridge"]) == 1\n\n\ndef test_predict_bridge_waits_for_first_actual_call_instead_of_calibrating_from_forecast():\n    _video, packed, shapes, contract, binding, guider, executor = _predict_bridge_fixture(actual=False)\n\n    forecast = flow_predict_wrapper(\n        executor,\n        packed,\n        torch.tensor([0.6]),\n        guider.model_options,\n        7,\n    )\n    assert torch.equal(forecast, packed)\n    assert contract["applied"] is False\n    assert not [event for event in binding.metrics.events if event.kind == "exact_prefix_suffix_dc_bridge"]\n\n    guider.model_options["transformer_options"][SPECTRUM_ACTUAL_KEY] = True\n    actual = flow_predict_wrapper(\n        executor,\n        packed,\n        torch.tensor([0.5]),\n        guider.model_options,\n        7,\n    )\n    actual_video, _ = unpack_streams(actual, shapes)\n    assert torch.equal(actual_video[:, :, 1], torch.full_like(actual_video[:, :, 1], 4.0))\n    assert contract["applied"] is True\n'''
)

# README: keep the main page concise, but make the shared control discoverable.
replace_once(
    "README.md",
    '''Keep audio unchanged. See [wiring and limitations](docs/CONTINUUM_DECODE_CONTEXT.md).\n\n### 3. Experimental exact-prefix Continuum acceleration\n''',
    '''Keep audio unchanged. See [wiring and limitations](docs/CONTINUUM_DECODE_CONTEXT.md).\n\nAll three Continuum progressive nodes expose `suffix_dc_bridge`, enabled by default on canonical whole-frame exact-prefix boundaries. The bridge changes only the first generated suffix latent token with a per-channel DC offset; it never edits the authoritative prefix or later suffix tokens. Mixed-Grid derives the offset from its discarded learned-upscaler prefix, while Target Input fallback and Target-Sparse derive it from the first actual H3 predicted-clean boundary before native mask restoration. Disable it only for matched seam A/B testing.\n\n### 3. Experimental exact-prefix Continuum acceleration\n''',
)

# Usage guide: explain the common mechanism and the two calibration sources.
replace_once(
    "docs/USAGE.md",
    '''If the prepared video denoise mask contains any exact-zero values, the exact native-masked contract takes precedence over progressive resizing. Flow forwards the original target noise, latent, mask, schedule, sampler, callback, and shape metadata through one ordinary target-grid sampler lifetime. No private noise, spatial transfer, exact probe, history boundary, or progressive guidance is used. A `progressive_target_fallback` metrics event records this path. Audio-only zero masks do not trigger it, and fractional video masks remain intentional blends rather than exact protection.\n\n### What happens at the handoff\n''',
    '''If the prepared video denoise mask contains any exact-zero values, the exact native-masked contract takes precedence over progressive resizing. Flow forwards the original target noise, latent, mask, schedule, sampler, callback, and shape metadata through one ordinary target-grid sampler lifetime. No private noise, spatial transfer, exact probe, history boundary, or progressive guidance is used. A `progressive_target_fallback` metrics event records this path. Audio-only zero masks do not trigger it, and fractional video masks remain intentional blends rather than exact protection.\n\n### Exact-prefix suffix DC bridge\n\nThe Continuum-facing **Progressive Handoff (Target Input)**, **Progressive Target-Sparse Continuum**, and **Progressive Mixed-Grid Continuum** nodes expose `suffix_dc_bridge`. It defaults to **on** and is only defined for a canonical whole-frame exact prefix followed by a whole-frame generated suffix. Partial/fractional/noncontiguous masks are skipped rather than guessed.\n\nThe correction is intentionally one latent token wide. Flow computes a per-batch/per-channel spatial-mean offset and applies it only to the first generated suffix token. The authoritative prefix and every later suffix token remain unchanged at bridge application. There is no video-space crossfade and no additional H3 transformer evaluation.\n\nThe calibration source depends on the progressive topology:\n\n- **Mixed-Grid:** use the discarded learned-upscaler prefix to preserve the learned transfer's native DC boundary relation when the exact target-grid prefix is restored.\n- **Target Input fallback / Target-Sparse high stage:** use the first **actual** H3 predicted-clean output at the exact boundary before native inpaint masking restores the protected prefix. Spectrum forecasts are not used as calibration; the bridge waits for the first actual model output. Target-Sparse already requires its first high-stage call to be actual. The conservative fallback reports `exact_prefix_suffix_dc_bridge_skipped` with `reason=no_actual_model_output` if a surrounding policy never produces an actual H3 evaluation.\n\nThe mixed-grid placement passed the matched decoded-media seam test that motivated enabling the control by default. The generalized Target Input and Target-Sparse placements are structurally covered by CI but should still be included in matched decoded-media validation for those topologies.\n\n### What happens at the handoff\n''',
)

# Mixed-grid doc: replace the old opt-in-only section with the shared contract.
mixed = Path("docs/MIXED_GRID_CONTINUUM.md")
text = mixed.read_text()
start = text.index("## Experimental suffix DC bridge\n")
end = text.index("## Validation and remaining acceptance\n", start)
section = '''## Shared suffix DC bridge\n\n`suffix_dc_bridge` defaults to **on** on all Continuum progressive nodes. The common contract is deliberately narrow: a canonical whole-frame exact prefix, one generated suffix boundary, a per-channel spatial-mean correction, and exactly one corrected suffix latent token. The authoritative prefix and every later suffix token remain unchanged. No video-space crossfade or extra H3 NFE is introduced.\n\nMixed-Grid has the strongest calibration source because its learned 3D transfer produces a complete target-grid clean sequence before the authoritative prefix is restored. Flow measures the per-channel spatial mean difference between the last discarded learned prefix token `U_prefix[-1]` and `P_exact[-1]`, then adds that difference only to `U_suffix[0]`. The corrected exact boundary therefore carries the learned upscaler's native `U_suffix[0] - U_prefix[-1]` DC relation while preserving `P_exact` bit-exactly.\n\nThe learned-transfer constructor already performs conditional re-noising. Flow recovers the clean learned estimate with the same deterministic noise, computes the clean-space delta, and maps only that suffix delta through `x_sigma = (1-sigma) * x0 + sigma * noise`. The deterministic noise is unchanged.\n\nThe other two Continuum progressive paths expose the same control without inventing a learned-prefix surrogate. Their exact-prefix sampler already evaluates H3 on the target grid, so they calibrate from the first **actual** H3 predicted-clean boundary before native mask restoration. Forecasts are deliberately not used for calibration. Target-Sparse guarantees an actual first high-stage call; the conservative Target Input fallback records a skip if no actual model output occurs.\n\n`mixed_grid_transfer` retains A/B/C diagnostics for native learned-upscaler, uncorrected exact restoration, and corrected exact restoration. `mixed_grid_complete` retains D after full target-grid refinement. The matched mixed-grid media gate removed the boundary flash with the one-token weight-1.0 correction; that result justifies the default for the shared control, but the generalized Target Input and Target-Sparse placements still require their own matched decoded-media checks.\n\n'''
mixed.write_text(text[:start] + section + text[end:])

# Target-sparse doc: document the high-stage placement and its actual-call invariant.
replace_once(
    "docs/TARGET_SPARSE_CONTINUUM.md",
    '''## Metrics to verify\n''',
    '''## Shared suffix DC bridge\n\nTarget-Sparse exposes the same `suffix_dc_bridge` control as the other Continuum progressive nodes and defaults it to **on**. It does not alter the sparse early transformer stage. The correction is installed only on the fresh full-grid high-stage sampler lifetime, after the hidden-space lifter boundary.\n\nFor a canonical whole-frame exact prefix, Flow snapshots the authoritative model-domain prefix and waits for the first **actual** high-stage H3 predicted-clean output. It compares the per-channel spatial mean of that output's last predicted prefix token with the authoritative last prefix token and applies the resulting constant offset only to the first generated suffix token. Native masking subsequently restores the protected prefix as usual. Later suffix tokens are untouched.\n\nThis composes with the existing target-sparse invariant that the first high-stage call must be actual. If the bridge is requested on a canonical boundary but no actual high-stage H3 evaluation consumes it, runtime fails rather than silently claiming success. Noncanonical masks emit a skip metric and keep the existing sampling behavior.\n\nThe bridge itself adds no H3 NFE. It is a seam correction, not an acceleration mechanism, and does not change the requirement to validate target-sparse decoded-media quality and timing independently.\n\n## Metrics to verify\n''',
)
